import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(
    df,
    fruits=None,
    days=None,
    seed=None,
    sales_lower_bound=1,
    sales_upper_bound=50,
):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError("'sales_lower_bound' must be less than 'sales_upper_bound'")

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]

    if days is None:
        days = 7

    if seed is not None:
        np.random.seed(seed)

    start_date = datetime.now()
    dates = [start_date + timedelta(days=i) for i in range(days)]

    records = [
        {
            "Date": date,
            "Fruit": fruit,
            "Sales": np.random.randint(
                sales_lower_bound, sales_upper_bound + 1
            ),
        }
        for date, fruit in itertools.product(dates, fruits)
    ]

    sales_df = pd.DataFrame(records)
    updated_df = pd.concat([df, sales_df], ignore_index=True)

    plot = sns.catplot(
        data=updated_df,
        x="Fruit",
        y="Sales",
        kind="box",
    )

    return updated_df, plot

