import re
import os
import subprocess

def task_func(dir_path, exe_pattern, execute_files=True):
    pattern = re.compile(exe_pattern)
    results = []

    if not os.path.isdir(dir_path):
        return results

    for entry in sorted(os.scandir(dir_path), key=lambda item: item.name):
        if (
            entry.is_file(follow_symlinks=True)
            and os.access(entry.path, os.X_OK)
            and pattern.search(entry.name)
        ):
            if execute_files:
                completed = subprocess.run(
                    [entry.path],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                results.append(completed.stdout)
            else:
                results.append(entry.path)

    return results

