import matplotlib.pyplot as plt


def task_func(file_path):
    """Find duplicate CSV rows and plot their occurrence counts."""
    if not str(file_path).lower().endswith(".csv"):
        raise ValueError("file_path must refer to a .csv file")

    try:
        with open(file_path, "r", newline="", encoding="utf-8") as csv_file:
            reader = csv.reader(csv_file, strict=True)
            rows = [tuple(row) for row in reader]
    except csv.Error as exc:
        raise ValueError("The CSV file is not properly formatted") from exc

    if rows:
        column_count = len(rows[0])
        if any(len(row) != column_count for row in rows):
            raise ValueError("The CSV file contains rows with inconsistent columns")

    counts = Counter(rows)
    duplicates = {
        row: count for row, count in counts.items() if count > 1
    }

    duplicate_df = pd.DataFrame(
        [
            {"row": ", ".join(row), "count": count}
            for row, count in duplicates.items()
        ],
        columns=["row", "count"],
    )

    ax = duplicate_df.plot(
        kind="bar",
        x="row",
        y="count",
        legend=False,
        xlabel="Duplicate row",
        ylabel="Count",
        title="Duplicate CSV rows",
    )

    return duplicates, ax

