import os
import base64


def task_func(raw_string, filename, output_dir):
    decoded = base64.b64decode(raw_string)
    data = json.loads(decoded.decode("utf-8"))

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    if isinstance(data, list):
        rows = data
    elif isinstance(data, dict):
        rows = [data]
    else:
        rows = [{"value": data}]

    if rows and all(isinstance(row, dict) for row in rows):
        fieldnames = []
        for row in rows:
            for key in row:
                if key not in fieldnames:
                    fieldnames.append(key)

        with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(rows)
    else:
        with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.writer(csv_file)
            for row in rows:
                writer.writerow(
                    [
                        json.dumps(row, ensure_ascii=False)
                        if isinstance(row, (dict, list))
                        else row
                    ]
                )

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    product_by_code = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description."
            )

        product_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains an invalid quantity or price."
            ) from exc

        if code not in product_by_code:
            product_by_code[code] = rng.choice(products)

        rows.append(
            [
                product_id,
                quantity,
                code,
                price,
                product_by_code[code],
                description,
            ]
        )

    return pd.DataFrame(rows, columns=columns)

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size <= 0 or subset_size > len(elements):
        return 1, Series([], dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    current_pid = os.getpid()
    process_ids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                fields = [field.strip().strip('"') for field in line.split('","')]
                if len(fields) >= 2 and fields[0].lower() == process_name.lower():
                    try:
                        pid = int(fields[1])
                        if pid != current_pid:
                            process_ids.append(pid)
                    except ValueError:
                        continue
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) == 2:
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue

                    if parts[1] == process_name and pid != current_pid:
                        process_ids.append(pid)
    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0
    for pid in process_ids:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (OSError, ProcessLookupError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

