import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)
    index = 0

    while True:
        suffix = '' if index == 0 else f'_{index}'
        backup_path = os.path.join(BACKUP_DIR, f'backup{suffix}')
        if not os.path.exists(backup_path):
            return backup_path
        index += 1


def task_func(directory):
    errors = []

    try:
        backup_directory = get_unique_backup_dir()
        os.makedirs(backup_directory)
    except Exception as error:
        return str(locals().get("backup_directory", "")), [str(error)]

    if not os.path.isdir(directory):
        return backup_directory, [f"Directory does not exist: {directory}"]

    for item_name in os.listdir(directory):
        source_path = os.path.join(directory, item_name)
        backup_path = os.path.join(backup_directory, item_name)

        try:
            if os.path.isdir(source_path) and not os.path.islink(source_path):
                shutil.copytree(source_path, backup_path)
            else:
                shutil.copy2(source_path, backup_path)
        except Exception as error:
            errors.append(str(error))
            continue

        try:
            if os.path.isdir(source_path) and not os.path.islink(source_path):
                shutil.rmtree(source_path)
            else:
                os.remove(source_path)
        except Exception as error:
            errors.append(str(error))

    return backup_directory, errors

