import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    """Compress files from src_folder and move them to dst_folder."""
    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    source_files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [os.path.basename(path) for path in source_files],
        }

    failed_files = []

    for index, source_path in enumerate(source_files):
        filename = os.path.basename(source_path)
        compressed_name = f"{filename}.gz"
        destination_path = os.path.join(dst_folder, compressed_name)
        temporary_path = os.path.join(
            dst_folder,
            f".{compressed_name}.{os.getpid()}.{index}.tmp",
        )

        try:
            with open(temporary_path, "wb") as output_file:
                process = subprocess.Popen(
                    ["gzip", "-c", source_path],
                    stdout=output_file,
                    stderr=subprocess.PIPE,
                )
                _, stderr = process.communicate()

            if process.returncode != 0:
                error = stderr.decode(errors="replace").strip()
                raise RuntimeError(error or "gzip returned a non-zero exit code")

            shutil.move(temporary_path, destination_path)
        except (OSError, RuntimeError) as exc:
            failed_files.append(filename)
            try:
                if os.path.exists(temporary_path):
                    os.remove(temporary_path)
            except OSError:
                pass

    success = not failed_files
    if success:
        message = (
            f"Successfully compressed and moved {len(source_files)} file(s)."
        )
    else:
        message = (
            f"Compressed and moved {len(source_files) - len(failed_files)} "
            f"of {len(source_files)} file(s)."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

