def task_func(input_list):
    def get_degree(element):
        if isinstance(element, dict):
            return element["degree"]
        if hasattr(element, "degree"):
            return element.degree
        if isinstance(element, (list, tuple)) and len(element) >= 2:
            return element[1]
        return element

