    sorted_stats = (
        statistics.mean(sorted_values),
        statistics.median(sorted_values),
        statistics.mode(sorted_values),
    )
    fft_stats = (
        statistics.mean(fft_magnitudes),
        statistics.median(fft_magnitudes),
        statistics.mode(fft_magnitudes.tolist()),
    )

    return tuple(round(value) for value in sorted_stats + fft_stats)

