import json
import re
import pandas as pd


def task_func(json_str):
    if not json_str or not isinstance(json_str, str):
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(
        r"(?<![\w.])-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
    )

    def normalize_value(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, (int, float)):
            return float(value * 2)

        if isinstance(value, str):
            stripped = value.strip()
            try:
                return float(stripped) * 2
            except ValueError:
                def replace_number(match):
                    return str(float(match.group(0)) * 2)

                return number_pattern.sub(replace_number, value)

        if isinstance(value, list):
            return [
                normalize_value(item) if not isinstance(item, dict) else item
                for item in value
            ]

        return value

    normalized = {
        key: normalize_value(value)
        for key, value in data.items()
    }

    try:
        list_lengths = [
            len(value)
            for value in normalized.values()
            if isinstance(value, list)
        ]
        target_length = max(list_lengths, default=1)

        dataframe_data = {}
        for key, value in normalized.items():
            if isinstance(value, list):
                dataframe_data[key] = value
            else:
                dataframe_data[key] = [value] * target_length

        return pd.DataFrame(dataframe_data)
    except (TypeError, ValueError):
        return pd.DataFrame()

