from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    """Extract text outside square brackets and return its TF-IDF scores."""
    text_without_brackets = re.sub(r"\[.*?\]", "", example_str, flags=re.DOTALL)

    if not text_without_brackets.strip():
        return {}

    vectorizer = TfidfVectorizer()
    tfidf_matrix = vectorizer.fit_transform([text_without_brackets])
