from difflib import ndiff


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, "r", encoding="utf-8", newline="") as file1:
            content1 = file1.read()

        with open(file_path2, "r", encoding="utf-8", newline="") as file2:
            content2 = file2.read()
    except FileNotFoundError:
        raise
    except OSError as exc:
        raise Exception("An error occurred while reading the files.") from exc

    if not content1 or not content2:
        raise ValueError("Neither file may be empty.")

    lines1 = content1.splitlines()
    lines2 = content2.splitlines()

