    line_number1 = 1
    line_number2 = 1

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[:1]
        line_content = diff_line[2:]

        if status == "?":
            continue

        if status == " ":
            differences.append(
                {
                    "Line Number": line_number1,
                    "Status": " ",
                    "Content": line_content,
                }
            )
            line_number1 += 1
            line_number2 += 1
        elif status == "-":
            differences.append(
                {
                    "Line Number": line_number1,
                    "Status": "-",
                    "Content": line_content,
                }
            )
            line_number1 += 1
        elif status == "+":
            differences.append(
                {
                    "Line Number": line_number2,
                    "Status": "+",
                    "Content": line_content,
                }
            )
            line_number2 += 1

    return pd.DataFrame(
        differences,
        columns=["Line Number", "Status", "Content"],
    )

