from sklearn.cluster import KMeans
import matplotlib.pyplot as plt
import numpy as np


def task_func(df1, df2, column1="feature1", column2="feature2"):
    """Merge two datasets, cluster paired features, and plot the results."""
    if column1 not in df1.columns:
        raise ValueError(f"Column {column1!r} was not found in df1.")
    if column2 not in df2.columns:
        raise ValueError(f"Column {column2!r} was not found in df2.")

    def id_candidates(df):
        return [
            column for column in df.columns
            if "id" in str(column).lower()
        ]

    common_ids = [column for column in df1.columns if column in df2.columns]
    common_id_candidates = [
        column for column in common_ids
        if "id" in str(column).lower()
    ]

    if common_id_candidates:
        left_id = right_id = common_id_candidates[0]
    elif common_ids:
        left_id = right_id = common_ids[0]
    else:
        left_candidates = id_candidates(df1)
        right_candidates = id_candidates(df2)
        if not left_candidates or not right_candidates:
            raise ValueError("Could not identify an ID column in both datasets.")
        left_id = left_candidates[0]
        right_id = right_candidates[0]

    left = df1[[left_id, column1]].rename(columns={column1: "_x"})
    right = df2[[right_id, column2]].rename(columns={column2: "_y"})

    merged = left.merge(
        right,
        left_on=left_id,
        right_on=right_id,
        how="inner",
    )

    if merged.empty:
        raise ValueError("The datasets have no matching IDs.")

    if merged[["_x", "_y"]].isnull().any().any():
        raise ValueError("Feature columns must not contain missing values.")

    features = merged[["_x", "_y"]].to_numpy()
    if features.shape[0] < 2:
        raise ValueError("At least two data points are required for two clusters.")

    model = KMeans(n_clusters=2, n_init=10)
    labels = np.asarray(model.fit_predict(features), dtype=np.int32)

    _, ax = plt.subplots()
    ax.scatter(features[:, 0], features[:, 1], c=labels)
    ax.set_xlabel(column1)
    ax.set_ylabel(column2)

    return labels, ax

