def task_func(source_dir: str, target_dir: str, archive_name: str = 'archive.zip') -> str:
    os.makedirs(target_dir, exist_ok=True)

    archive_path = os.path.join(target_dir, archive_name)
    archive_parent = os.path.dirname(archive_path)
    if archive_parent:
        os.makedirs(archive_parent, exist_ok=True)

    processed_files = []
    for root, _, files in os.walk(source_dir):
        for filename in files:
            stem, _ = os.path.splitext(filename)
            if re.search(r'_processed$', stem):
                path = os.path.join(root, filename)
                if os.path.abspath(path) != os.path.abspath(archive_path):
                    processed_files.append(path)

    with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as archive:
        for file_path in processed_files:
            archive.write(file_path, os.path.relpath(file_path, source_dir))

    return archive_path

