import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            command = ["wmic", "cpu", "get", "loadpercentage"]
        else:
            command = ["top", "-bn1"]

        cpu_usage = 0.0

        try:
            output = subprocess.check_output(
                command,
                stderr=subprocess.STDOUT,
                text=True
            )

            if isinstance(output, bytes):
                output = output.decode(errors="replace")

            if platform.system() == "Windows":
                for line in output.splitlines():
                    value = line.strip()
                    if value.isdigit():
                        cpu_usage = float(value)
                        break
            else:
                for line in output.splitlines():
                    if "id" in line:
                        for part in line.replace(",", " ").split():
                            if part.endswith("%id"):
                                cpu_usage = 100.0 - float(part[:-3])
                                break
                        break
        except (OSError, subprocess.SubprocessError, ValueError):
            cpu_usage = 0.0

        records.append({
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            "cpu_usage": cpu_usage
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

