import re
import socket

def task_func(ip_addresses: list) -> dict:
    """Map valid IP addresses to hostnames, or None when unresolved."""
    ipv4_pattern = re.compile(
        r"^(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)"
        r"(?:\.(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$"
    )

    result = {}

    for ip_address in ip_addresses:
        if not isinstance(ip_address, str):
            continue

        is_valid = bool(ipv4_pattern.fullmatch(ip_address))

        if not is_valid:
            try:
                socket.inet_pton(socket.AF_INET6, ip_address)
                is_valid = True
            except (AttributeError, OSError, ValueError):
                is_valid = False

        if not is_valid:
            continue

        try:
            result[ip_address] = socket.gethostbyaddr(ip_address)[0]
        except (socket.herror, socket.gaierror, OSError):
            result[ip_address] = None

    return result

