import re
import urllib.parse
import requests
import json


def task_func(myString, API_KEY):
    """Extract URLs, geolocate their domains, and return the API responses."""
    if not isinstance(myString, str):
        return {}

    url_pattern = re.compile(
        r"""(?i)\b(?:https?://|ftp://|www\.)[^\s<>"'()]+"""
    )
    urls = url_pattern.findall(myString)
    domains = []

    for url in urls:
        url = url.rstrip(".,!?;:]}>)")
        parsed = urllib.parse.urlparse(
            url if "://" in url else f"//{url}",
            scheme="" if "://" not in url else None,
        )
        domain = parsed.hostname
        if domain:
            domain = domain.lower().rstrip(".")
            if domain not in domains:
                domains.append(domain)

    result = {}

    for domain in domains:
        query = {}
        if API_KEY:
            query["key"] = API_KEY

        api_url = f"https://ip-api.com/json/{urllib.parse.quote(domain)}"
        if query:
            api_url = f"{api_url}?{urllib.parse.urlencode(query)}"

        try:
            response = requests.get(api_url, timeout=10)

            status_code = getattr(response, "status_code", 200)
            if status_code >= 400:
                result[domain] = None
                continue

            data = response.json()
            if isinstance(data, str):
                data = json.loads(data)

            result[domain] = data
        except (requests.RequestException, ValueError, TypeError, json.JSONDecodeError):
            result[domain] = None
        except Exception:
            result[domain] = None

    return result

