import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    processed_files = 0
    text_tag = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t"

    for file_path in glob.glob(f"{directory_path}/*.docx"):
        document = Document(file_path)
        roots = [document.element.body]
        seen_roots = {id(roots[0])}

        for section in document.sections:
            for container in (
                section.header,
                section.first_page_header,
                section.even_page_header,
                section.footer,
                section.first_page_footer,
                section.even_page_footer,
            ):
                root = container._element
                if id(root) not in seen_roots:
                    roots.append(root)
                    seen_roots.add(id(root))

        for root in roots:
            for text_node in root.iter(text_tag):
                if text_node.text:
                    text_node.text = re.sub(r'"', r'\\"', text_node.text)

        document.save(file_path)
        processed_files += 1

    return processed_files

import itertools
import math

def task_func(x):
    """Return a non-empty subsequence with the minimum total length."""
    if not x:
        return []

    keys = list(x)
    best_subsequence = []
    best_length = math.inf

    for size in range(1, len(keys) + 1):
        for combination in itertools.combinations(keys, size):
            total_length = sum(x[key] for key in combination)
            if total_length < best_length:
                best_length = total_length
                best_subsequence = list(combination)

    return best_subsequence

