import binascii
import hashlib
import re
import os

OUTPUT_DIR = './output'


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    regex = re.compile(pattern)
    hashes = {}

    for root, _, files in os.walk(directory):
        for filename in files:
            file_path = os.path.join(root, filename)
            windows_path = file_path.replace(os.sep, "\\")

            if not (regex.search(file_path) or regex.search(windows_path)):
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            hashes[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return hashes

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = json.loads(response.text)

        name_pattern = re.compile(r'"name"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"')
        names = []

        def extract(value, inside_brackets=False):
            if isinstance(value, dict):
                for key, item in value.items():
                    if key == "name" and isinstance(item, str) and not inside_brackets:
                        match = name_pattern.search(
                            json.dumps({"name": item}, ensure_ascii=False)
                        )
                        if match and not re.fullmatch(r"\s*\[.*\]\s*", item):
                            names.append(item)
                    extract(item, inside_brackets)
            elif isinstance(value, list):
                for item in value:
                    extract(item, True)

        extract(data)
        return names
    except Exception:
        return "Invalid url input"

