import os
import sys
import importlib
from pkgutil import iter_modules


def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Package '{package_name}' is not installed. "
            f"Please install it with: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)
    if package_paths is None:
        package_file = getattr(package, "__file__", None)
        package_paths = [os.path.dirname(package_file)] if package_file else []

    module_names = []
    for package_path in package_paths:
        package_path = os.fspath(package_path)

        if package_path not in sys.path:
            sys.path.append(package_path)

        for module_info in iter_modules([package_path]):
            if module_info.name not in module_names:
                module_names.append(module_info.name)

    return module_names

