def task_func(filepath):
    """Compile a C++ source file and log the compilation result."""
    try:
        with open(filepath, "rb"):
            pass
    except FileNotFoundError:
        logging.error("C++ source file not found: %s", filepath)
        raise

    try:
        result = subprocess.run(
            ["g++", filepath],
            check=True,
            capture_output=True,
            text=True,
        )

        if result.stdout:
            logging.info("Compiler output:\n%s", result.stdout.strip())
        if result.stderr:
            logging.info("Compiler diagnostics:\n%s", result.stderr.strip())

        logging.info("Compilation successful: %s", filepath)
    except subprocess.CalledProcessError as error:
        output = error.stderr or error.stdout or str(error)
        logging.error("Compilation failed for %s:\n%s", filepath, output.strip())
        raise
    except FileNotFoundError:
        logging.error("C++ compiler not found.")
        raise

