import re
import pandas as pd
from datetime import datetime
import os


def task_func(log_file):
    pattern = re.compile(
        r"^(?P<message_type>[^:]+):\s*\[(?P<timestamp>[^\]]+)\]\s*-\s*(?P<message>.*)$"
    )

    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            line = line.rstrip("\n")
            match = pattern.match(line)

            if not match:
                continue

            timestamp = match.group("timestamp")

            try:
                parsed_timestamp = datetime.strptime(
                    timestamp, "%Y-%m-%d %H:%M:%S"
                )
            except ValueError as exc:
                raise ValueError(
                    f"Invalid timestamp in log entry: {timestamp}"
                ) from exc

            entries.append(
                {
                    "Type": match.group("message_type").strip(),
                    "Timestamp": parsed_timestamp.strftime("%Y-%m-%d %H:%M:%S"),
                    "Message": match.group("message"),
                }
            )

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = os.path.splitext(log_file)[0] + "_structured.csv"
    pd.DataFrame(entries).to_csv(output_file, index=False)

    return output_file

