import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """Retrieve API data, create a DataFrame, and plot its numerical correlations."""
    try:
        if not isinstance(url, str) or not url.strip():
            raise Exception("The URL must be a non-empty string.")

        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=30
        )
        response.raise_for_status()

        data = response.json()

        if not data:
            raise Exception("The API returned empty data.")

        if isinstance(data, dict):
            for key in ("data", "results", "items"):
                if key in data:
                    data = data[key]
                    break

        if isinstance(data, list):
            dataframe = pd.DataFrame(data)
        elif isinstance(data, dict):
            dataframe = pd.DataFrame([data])
        else:
            raise Exception("The API returned invalid data.")

        if dataframe.empty:
            raise Exception("The API returned empty data.")

        numerical_data = dataframe.select_dtypes(include="number")

        if numerical_data.empty:
            raise Exception("The data contains no numerical characteristics.")

        if not numerical_data.notna().any().any():
            raise Exception("The numerical data is invalid.")

        correlation = numerical_data.corr()

        if correlation.empty:
            raise Exception("Unable to calculate correlations.")

        axes = sns.heatmap(
            correlation,
            annot=True,
            cmap="coolwarm",
            center=0,
            square=True
        )
        plt.show()

        return dataframe, axes

    except Exception as error:
        raise Exception(f"Unable to retrieve or process API data: {error}") from error

import random
import re


def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

