import numpy as np
from itertools import zip_longest


def task_func(l1, l2, THRESHOLD=0.5):
    sentinel = object()
    candidates = []

    for first, second in zip_longest(l1, l2, fillvalue=sentinel):
        for value in (first, second):
            if value is sentinel or isinstance(value, (bool, np.bool_)):
                continue
            if isinstance(value, (int, float, np.integer, np.floating)):
                if not np.isnan(value):
                    candidates.append(value)

    if not candidates:
        return np.nan

    return float(min(candidates, key=lambda value: abs(value - THRESHOLD)))

