import struct
import io
import gzip
def task_func(newArray):
    dtype = newArray.dtype
    kind = dtype.kind
    size = dtype.itemsize

    formats = {
        ("b", 1): "b", ("b", 2): "h", ("b", 4): "i", ("b", 8): "q",
        ("i", 1): "b", ("i", 2): "h", ("i", 4): "i", ("i", 8): "q",
        ("u", 1): "B", ("u", 2): "H", ("u", 4): "I", ("u", 8): "Q",
        ("f", 2): "e", ("f", 4): "f", ("f", 8): "d",
        ("b", 1): "b",
        ("?", 1): "?",
    }

    with io.BytesIO() as buffer:
        with gzip.GzipFile(fileobj=buffer, mode="wb") as gzip_file:
            if kind == "c" and size in (8, 16):
                component_format = "f" if size == 8 else "d"
                values = []
                for value in newArray.ravel(order="C"):
                    values.extend((value.real, value.imag))
                if values:
                    packed = struct.pack(
                        f"{len(values)}{component_format}", *values
                    )
                    gzip_file.write(packed)
            elif (kind, size) in formats:
                values = newArray.ravel(order="C")
                format_code = formats[(kind, size)]
                chunk_size = 65536
                for start in range(0, len(values), chunk_size):
                    chunk = values[start:start + chunk_size]
                    gzip_file.write(
                        struct.pack(f"{len(chunk)}{format_code}", *chunk)
                    )
            else:
                gzip_file.write(newArray.tobytes(order="C"))

        return buffer.getvalue()

