# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]


def task_func(rows, columns):
    """Generate a DataFrame containing randomly generated values."""
    if not isinstance(rows, int) or not isinstance(columns, int):
        raise TypeError("rows and columns must be integers")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    def random_int():
        return int(np.random.randint(0, 10))

    def random_string():
        return "".join(choice("abcdefghijklmnopqrstuvwxyz") for _ in range(5))

    def random_list():
        length = int(np.random.randint(1, 6))
        return [random_int() for _ in range(length)]

    def random_tuple():
        length = int(np.random.randint(1, 6))
        return tuple(random_int() for _ in range(length))

    def random_dict():
        length = int(np.random.randint(1, 6))
        keys = np.random.choice(10, size=length, replace=False)
        return {int(key): random_int() for key in keys}

    def random_set():
        length = int(np.random.randint(1, 6))
        return {int(value) for value in np.random.choice(10, size=length, replace=False)}

    generators = {
        str: random_string,
        int: random_int,
        float: lambda: float(random_int()),
        list: random_list,
        tuple: random_tuple,
        dict: random_dict,
        set: random_set,
    }

    data = {}
    for column_index in range(columns):
        data_type = choice(DATA_TYPES)
        generator = generators[data_type]
        data[f"col{column_index}"] = [generator() for _ in range(rows)]

    return pd.DataFrame(data)

