from sklearn.feature_extraction.text import CountVectorizer
# Make sure to download NLTK stopwords
nltk.download('stopwords')
# Define a regex pattern for matching all non-alphanumeric characters
ALPHANUMERIC = re.compile('[\W_]+')
# Load NLTK's list of English stop words
STOPWORDS = nltk.corpus.stopwords.words('english')


def task_func(texts):
    """Create a document-term matrix from a list of text documents."""
    cleaned_texts = [
        ALPHANUMERIC.sub(' ', str(text)).lower()
        for text in texts
    ]

    vectorizer = CountVectorizer(stop_words=STOPWORDS)

    if not cleaned_texts:
        return pd.DataFrame()

    try:
        matrix = vectorizer.fit_transform(cleaned_texts)
    except ValueError as error:
        if str(error) == "empty vocabulary; perhaps the documents only contain stop words":
            return pd.DataFrame(index=range(len(cleaned_texts)))
        raise

    return pd.DataFrame(
        matrix.toarray(),
        index=range(len(cleaned_texts)),
        columns=vectorizer.get_feature_names_out(),
    )

