def task_func(file_name):
    with open(file_name, "r", encoding="utf-8", newline="") as file:
        reader = csv.reader(file)

        try:
            column_names = next(reader)
        except StopIteration:
            return {}

        counts = {column: collections.Counter() for column in column_names}
        has_data = False

        for row in reader:
            if not row:
                continue

            has_data = True
            for index, column in enumerate(column_names):
                if index < len(row):
                    counts[column][row[index]] += 1

        if not has_data:
            return {}

        result = {}
        for column, counter in counts.items():
            if counter:
                maximum = max(counter.values())
                candidates = [
                    value for value, count in counter.items()
                    if count == maximum
                ]
                result[column] = min(candidates)

        return result

