# Constants
REPLACE_NONE = "None"

_EMAIL_PATTERN = re.compile(
    r"(?<![\w.-])[\w.!#$%&'*+/=?^`{|}~-]+@[\w-]+(?:\.[\w-]+)+(?![\w.-])"
)


def task_func(json_str):
    data = json.loads(json_str)

    def remove_none(value):
        if isinstance(value, dict):
            return {
                key: remove_none(item)
                for key, item in value.items()
                if item is not None
            }
        if isinstance(value, list):
            return [
                remove_none(item)
                for item in value
                if item is not None
            ]
        return value

    def count_values(value, counts):
        if isinstance(value, dict):
            for item in value.values():
                count_values(item, counts)
        elif isinstance(value, list):
            for item in value:
                count_values(item, counts)
        else:
            try:
                counts[value] += 1
            except TypeError:
                counts[str(value)] += 1

    def replace_emails(value):
        if isinstance(value, dict):
            return {
                key: replace_emails(item)
                for key, item in value.items()
            }
        if isinstance(value, list):
            return [replace_emails(item) for item in value]
        if isinstance(value, str):
            return _EMAIL_PATTERN.sub(REPLACE_NONE, value)
        return value

    processed_data = remove_none(data)
    value_counts = Counter()
    count_values(processed_data, value_counts)
    processed_data = replace_emails(processed_data)

    return {
        "data": processed_data,
        "value_counts": value_counts,
    }

