import pandas as pd
import seaborn as sns

def task_func(list_of_menuitems):
    """Flatten nested menu items and plot their frequencies."""
    if not list_of_menuitems:
        return None

    flattened_items = []
    stack = list(reversed(list_of_menuitems))

    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(reversed(item))
        else:
            flattened_items.append(item)

    item_counts = Counter(flattened_items)

    if not item_counts:
        return None

    data = pd.DataFrame(
        item_counts.items(),
        columns=["menu_item", "frequency"],
    )

    return sns.barplot(
        data=data,
        x="menu_item",
        y="frequency",
    )

import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    keys = [key for key in mapping if isinstance(key, str) and key]
    if not keys:
        return result

    keys.sort(key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in keys) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if not isinstance(value, str):
            return value

        return pattern.sub(
            lambda match: str(mapping[match.group(0)]),
            value,
        )

    for column in result.columns:
        result[column] = result[column].map(replace_acronyms)

    return result

import random
import bisect
from array import array
def task_func(n=10, total=100):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if not isinstance(total, int) or isinstance(total, bool):
        raise TypeError("total must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        if total != 0:
            raise ValueError("total must be zero when n is zero")
        return array("i"), 0

    sign = -1 if total < 0 else 1
    magnitude = abs(total)
    numbers = None

    for _ in range(100):
        candidate = [random.randint(0, magnitude) for _ in range(n)]
        if sum(candidate) == magnitude:
            numbers = candidate
            break

    if numbers is None:
        cuts = sorted(random.randint(0, magnitude) for _ in range(n - 1))
        boundaries = [0, *cuts, magnitude]
        numbers = [
            boundaries[index + 1] - boundaries[index]
            for index in range(n)
        ]

    numbers = sorted(sign * number for number in numbers)
    result = array("i", numbers)

    low = numbers[0]
    high = numbers[-1]
    new_number = random.randint(low, high)
    insertion_position = bisect.bisect_left(result, new_number)

    return result, insertion_position

