import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    path = Path(dir_path)

    if not path.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        if callable(predicate):
            key = ("callable", id(predicate))
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)
        elif isinstance(predicate, re.Pattern):
            key = ("pattern", predicate.pattern, predicate.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)
        elif isinstance(predicate, str):
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue

            key = ("pattern", compiled.pattern, compiled.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(compiled)

    if not valid_predicates:
        raise ValueError("No valid predicates provided")

    result = {}

    for name in os.listdir(path):
        checks = []

        for predicate in valid_predicates:
            if callable(predicate) and not isinstance(predicate, re.Pattern):
                checks.append(bool(predicate(name)))
            else:
                checks.append(bool(predicate.search(name)))

        result[name] = checks

    return result

import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must be non-negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    patterns = []
    for target in target_words:
        target = str(target).lower()
        if target:
            pattern = re.escape(target).replace(r"\ ", r"\s+")
            patterns.append(
                (
                    re.compile(rf"(?<!\w){pattern}(?!\w)", re.IGNORECASE),
                    target.replace(" ", "_"),
                )
            )

    sentences = []
    for _ in range(n_sentences):
        words = random.choices(vocabulary, k=10)
        sentence = " ".join(str(word) for word in words).lower()

        for pattern, replacement in patterns:
            sentence = pattern.sub(replacement, sentence)

        sentences.append(sentence)

    return sentences

