import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    token_pattern = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[{}]')
    tokens = list(token_pattern.finditer(text))

    stack = []
    pairs = {}

    for token in tokens:
        value = token.group()
        if value == "{":
            stack.append(token)
        elif value == "}" and stack:
            opening = stack.pop()
            pairs[opening.start()] = token.end()

    dictionaries = []
    consumed_end = -1

    for start in sorted(pairs):
        if start < consumed_end:
            continue

        candidate = text[start:pairs[start]]

        try:
            value = ast.literal_eval(candidate)
        except (SyntaxError, ValueError):
            continue

        if isinstance(value, dict):
            dictionaries.append(value)
            consumed_end = pairs[start]

    return dictionaries

