    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch_milliseconds.") from exc

    current_datetime = datetime.now()

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot represent a future time.")

    random_generator = random.Random(random_seed)
    dates = pd.date_range(
        start=start_datetime.date(),
        end=current_datetime.date(),
        freq="D",
    )

    data = [
        {
            "Product": product,
            "Date": date.to_pydatetime(),
            "Sales": random_generator.randint(10, 50),
        }
        for date in dates
        for product in products
    ]

    return pd.DataFrame(data, columns=["Product", "Date", "Sales"])

