import os
import pandas as pd
from datetime import datetime


def task_func(
    excel_directory: str,
    file_name: str,
    column_name: str,
    start_date: str,
    end_date: str,
) -> pd.DataFrame:
    file_path = os.path.join(excel_directory, file_name)

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Excel file not found: {file_path}")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")
    except (TypeError, ValueError) as exc:
        raise ValueError("Dates must be in YYYY-MM-DD format.") from exc

    data = pd.read_excel(file_path)

    if column_name not in data.columns:
        raise ValueError(f"Column not found: {column_name}")

    dates = pd.to_datetime(data[column_name], errors="coerce")
    mask = dates.between(start, end, inclusive="both")

    return data.loc[mask].copy()

import json
import requests
import chardet

# Constants
API_URL = "http://api.example.com/data"


def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    encoding = from_encoding
    if encoding is None:
        encoding = chardet.detect(content).get("encoding")

    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")

    decoded_content = content.decode(encoding)
    re_encoded_content = decoded_content.encode(to_encoding)

    return json.loads(re_encoded_content)

