import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    try:
        duration = float(run_duration)
        if duration < 0:
            raise ValueError("run_duration must be non-negative")
        if int(buffer_size) <= 0:
            raise ValueError("buffer_size must be positive")
    except (TypeError, ValueError) as exc:
        return f"Server failed to start: {exc}"

    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clients = []
    output_queues = {}
    pending_data = {}
    started_at = datetime.now()
    deadline = started_at + timedelta(seconds=duration)

    def close_client(client):
        if client in clients:
            clients.remove(client)
        output_queues.pop(client, None)
        pending_data.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        while True:
            remaining = (deadline - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            read_sockets = [server_socket, *clients]
            write_sockets = [
                client
                for client in clients
                if pending_data.get(client)
                or not output_queues[client].empty()
            ]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    read_sockets,
                    write_sockets,
                    exceptional_sockets,
                    remaining,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.append(client)
                        output_queues[client] = queue.Queue()
                        pending_data[client] = bytearray()
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client in list(exceptional):
                if client is not server_socket and client in clients:
                    close_client(client)

            for client in list(readable):
                if client is server_socket or client not in clients:
                    continue
                try:
                    data = client.recv(int(buffer_size))
                    if not data:
                        close_client(client)
                        continue
                    response = data + str(datetime.now()).encode("utf-8")
                    output_queues[client].put(response)
                except (BlockingIOError, InterruptedError):
                    continue
                except (ConnectionError, OSError):
                    close_client(client)

            for client in list(writable):
                if client not in clients:
                    continue
                try:
                    if not pending_data[client] and not output_queues[client].empty():
                        pending_data[client].extend(output_queues[client].get_nowait())

                    if pending_data[client]:
                        sent = client.send(pending_data[client])
                        del pending_data[client][:sent]
                except (queue.Empty, BlockingIOError, InterruptedError):
                    continue
                except (ConnectionError, OSError):
                    close_client(client)

    except OSError as exc:
        return f"Server failed to start or operate: {exc}"
    finally:
        for client in list(clients):
            close_client(client)
        try:
            server_socket.close()
        except OSError:
            pass

    elapsed = (datetime.now() - started_at).total_seconds()
    return f"Echo server operated for {elapsed:.2f} seconds."

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if not isinstance(N, (int, np.integer)) or N < 0:
        raise ValueError("N must be a non-negative integer")

    categories = list(CATEGORIES)
    if N > 0 and not categories:
        raise ValueError("CATEGORIES must not be empty when N is positive")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N < len(categories):
        assigned_categories = rng.choice(categories, size=N, replace=False)
    else:
        assigned_categories = np.concatenate(
            [
                np.asarray(categories, dtype=object),
                rng.choice(categories, size=N - len(categories), replace=True),
            ]
        )
        rng.shuffle(assigned_categories)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": assigned_categories,
        }
    )

    fig, ax = plt.subplots()
    for category in categories:
        subset = df[df["category"] == category]
        ax.scatter(
            subset["x"],
            subset["y"],
            label=str(category),
        )

    if categories:
        ax.legend()

    ax.set_xlabel("x")
    ax.set_ylabel("y")

    return df, ax

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if not isinstance(start_year, int) or not isinstance(end_year, int):
        raise TypeError("start_year and end_year must be integers")
    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")
    if start_year < 0 or end_year > 9999:
        raise ValueError("years must be between 0 and 9999")
    if not email_domain:
        raise ValueError("email_domain must not be empty")

    names = list(latin_names) + list(other_names)
    if not names:
        raise ValueError("at least one name must be provided")

    def correct_encoding(value):
        text = str(value)

        if "\\u" in text or "\\x" in text:
            try:
                text = codecs.decode(text, "unicode_escape")
            except UnicodeDecodeError:
                pass

        for _ in range(2):
            if not re.search(r"(Ã.|Â.|â..|ð.)", text):
                break
            try:
                corrected = text.encode("latin1").decode("utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                break
            if corrected == text:
                break
            text = corrected

        return text

    rng = np.random.default_rng(rng_seed)
    selected_names = rng.choice(names, size=100)

    dates = []
    for _ in range(100):
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        if year == 0:
            day = int(rng.integers(1, 29))
            date_value = f"{year:04d}-{month:02d}-{day:02d}"
        else:
            days_in_month = (
                datetime.date(year + (month == 12), (month % 12) + 1, 1)
                - datetime.timedelta(days=1)
            ).day
            day = int(rng.integers(1, days_in_month + 1))
            date_value = datetime.datetime(year, month, day)

        dates.append(date_value)

    corrected_names = [correct_encoding(name) for name in selected_names]
    emails = [
        f"{name.lower()}{date.year if isinstance(date, datetime.datetime) else int(date[:4])}@{email_domain}"
        for name, date in zip(corrected_names, dates)
    ]

    return pd.DataFrame({
        "ID": np.arange(1, 101),
        "Name": corrected_names,
        "Date of Birth": dates,
        "Email": emails,
    })

