        pd.DataFrame(choices(L, k=3), columns=column_names)
        for _ in range(num_dataframes)
    ]

    common_keys = {
        tuple(row) for row in df_list[0].itertuples(index=False, name=None)
    }

    for df in df_list[1:]:
        keys = {
            tuple(row) for row in df.itertuples(index=False, name=None)
        }
        common_keys &= keys

    common_rows = df_list[0][
        df_list[0].apply(
            lambda row: tuple(row) in common_keys,
            axis=1,
        )
    ].copy()

    return common_rows, df_list

