def task_func(hex_str):
    if not isinstance(hex_str, str):
        raise ValueError("'hex_str' must be a valid hex string.")

    if "\\x" in hex_str:
        if not hex_str.startswith("\\x"):
            raise ValueError("'hex_str' must be a valid hex string.")

        payload = hex_str[2:]
        if "\\x" in payload:
            parts = payload.split("\\x")
            if any(len(part) != 2 for part in parts):
                raise ValueError("'hex_str' must be a valid hex string.")
            payload = "".join(parts)

    else:
        payload = hex_str

    try:
        byte_data = binascii.unhexlify(payload.encode("ascii"))
    except (binascii.Error, UnicodeEncodeError):
        raise ValueError("'hex_str' must be a valid hex string.")

    values, frequencies = np.unique(
        np.frombuffer(byte_data, dtype=np.uint8),
        return_counts=True,
    )

    frequency_df = pd.DataFrame(
        {
            "Byte Value": values,
            "Frequency": frequencies,
        }
    )

    _, ax = plt.subplots()
    ax.bar(frequency_df["Byte Value"], frequency_df["Frequency"])
    ax.set_xlabel("Byte Value")
    ax.set_ylabel("Frequency")

    return frequency_df, ax

import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_indices = [
            index for index, word in enumerate(words)
            if regex.fullmatch(word)
        ]
        matching_words = [words[index] for index in matching_indices]

        for index, word in zip(matching_indices, reversed(matching_words)):
            words[index] = word

        return " ".join(words)

    result = df.copy()
    result[column_name] = result[column_name].map(reverse_matching_words)
    return result

