import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"Unable to read valid JSON from file: {file_path}") from exc

    expected_root_type = INPUT_JSON.get("type", "object")
    if expected_root_type == "object":
        if not isinstance(data, dict):
            raise ValueError("JSON root must be an object")
    elif isinstance(expected_root_type, type) and not isinstance(data, expected_root_type):
        raise ValueError("JSON root type does not match the schema")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    for field, schema in properties.items():
        if field not in data:
            continue

        expected_type = schema.get("type")
        value = data[field]

        if isinstance(expected_type, type):
            if type(value) is not expected_type:
                raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "string" and not isinstance(value, str):
            raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "integer" and (
            type(value) is not int
        ):
            raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "number" and (
            not isinstance(value, (int, float)) or isinstance(value, bool)
        ):
            raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "boolean" and not isinstance(value, bool):
            raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "object" and not isinstance(value, dict):
            raise ValueError(f"Invalid type for attribute: {field}")
        elif expected_type == "array" and not isinstance(value, list):
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" in data:
        if not isinstance(data["email"], str) or re.fullmatch(
            EMAIL_REGEX, data["email"]
        ) is None:
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    return data[attribute]

