import pandas as pd


def task_func(l, n_groups=5):
    """Return a shuffled, repeated Series with randomly rotated strings."""
    if not l or n_groups <= 0:
        return pd.Series(dtype=object)

    items = list(l)
    shuffle(items)

    repeated = [items[i % len(items)] for i in range(len(items) * n_groups)]
    result = []

    for item in repeated:
        text = str(item)
        n = randint(0, min(n_groups, len(text)))
        result.append(text[n:] + text[:n])

    return pd.Series(result)

