import shutil
from pathlib import Path
from typing import List


def task_func(source_dir: str, target_dir: str, extensions: List[str]) -> int:
    source = Path(source_dir)
    target = Path(target_dir)

    if not source.exists() or not target.exists():
        raise ValueError("Source or target directory does not exist.")

    if not source.is_dir() or not target.is_dir():
        raise ValueError("Source or target path is not a directory.")

    if source.resolve() == target.resolve():
        return 0

    normalized_extensions = {
        extension.lower() if extension.startswith(".") else f".{extension.lower()}"
        for extension in extensions
    }

    moved_count = 0

    for file_path in source.iterdir():
        if file_path.is_file() and file_path.suffix.lower() in normalized_extensions:
            shutil.move(str(file_path), str(target / file_path.name))
            moved_count += 1

    return moved_count

