import numpy as np
import random
from datetime import datetime


def task_func(
    rows=3,
    columns=2,
    start_date=datetime(2021, 1, 1),
    end_date=datetime(2021, 12, 31),
    seed=0,
):
    from datetime import timedelta
    import operator

    try:
        rows = operator.index(rows)
        columns = operator.index(columns)
    except TypeError as exc:
        raise TypeError("rows and columns must be integers") from exc

    if isinstance(rows, bool) or isinstance(columns, bool):
        raise TypeError("rows and columns must be integers")

    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise TypeError("start_date and end_date must be datetime objects")

    if end_date < start_date:
        raise ValueError("end_date must not precede start_date")

    total = rows * columns
    available = (end_date - start_date).days + 1

    if total > available:
        raise ValueError("The date range does not contain enough unique dates")

    rng = random.Random(seed)
    offsets = rng.sample(range(available), total)
    dates = [start_date + timedelta(days=offset) for offset in offsets]

    return np.asarray(dates, dtype=object).reshape(rows, columns)

