from collections import Counter

def task_func(folder_path: str) -> dict:
    ip_pattern = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")
    counts = Counter()

    try:
        entries = os.scandir(folder_path)
    except OSError:
        return {}

    with entries:
        for entry in entries:
            if not entry.is_file() or not entry.name.lower().endswith(".log"):
                continue

            try:
                with open(entry.path, "r", encoding="utf-8", errors="ignore") as file:
                    for line in file:
                        counts.update(ip_pattern.findall(line))
            except OSError:
                continue

    return dict(counts)

