import os
from pathlib import Path
import shutil

def task_func(kwargs, target_dir="non_none_files"):
    copied_files = []
    target_path = Path(target_dir)
    target_path.mkdir(parents=True, exist_ok=True)

    for file_path in kwargs.values():
        if file_path is None:
            continue

        try:
            source_path = Path(file_path)
        except (TypeError, ValueError):
            continue

        if not source_path.is_file() or source_path.stat().st_size == 0:
            continue

        destination_path = target_path / source_path.name

        if source_path.resolve() == destination_path.resolve():
            copied_files.append(str(destination_path.resolve()))
            continue

        shutil.copy2(source_path, destination_path)
        copied_files.append(str(destination_path.resolve()))

    return {"copied_files": copied_files}

