import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if (
        not isinstance(date_str, str)
        or len(date_str) != 10
        or date_str[4] != "-"
        or date_str[7] != "-"
    ):
        raise ValueError("date_str must follow the yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.now().date():
        raise ValueError("date_str must not refer to a past date")

    def matches_date(value):
        if isinstance(value, datetime):
            return value.date() == requested_date

        if hasattr(value, "date") and not isinstance(value, str):
            return value.date() == requested_date

        if isinstance(value, str):
            try:
                return datetime.strptime(value, "%Y-%m-%d").date() == requested_date
            except ValueError:
                return False

        return value == requested_date

    def is_booked(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, dict):
            for key in ("date", "booking_date", "booked_date"):
                if key in value and matches_date(value[key]):
                    return True

            for key in ("dates", "booking_dates", "bookings"):
                if key in value and is_booked(value[key]):
                    return True

            if "status" in value:
                return str(value["status"]).lower() in {
                    "booked",
                    "reserved",
                    "unavailable",
                }

            return any(matches_date(key) for key in value)

        if isinstance(value, (list, tuple, set, pd.Series)):
            return any(is_booked(item) for item in value)

        return matches_date(value)

    booked_rooms = set()

    if isinstance(booking_data, pd.DataFrame):
        for _, row in booking_data.iterrows():
            room = row.get("room", row.get("Room"))
            booking_date = row.get(
                "date", row.get("booking_date", row.get("Date"))
            )
            if room in ROOMS and (
                matches_date(booking_date)
                or str(row.get("status", "")).lower()
                in {"booked", "reserved", "unavailable"}
            ):
                booked_rooms.add(room)

    elif isinstance(booking_data, dict):
        for room in ROOMS:
            if room in booking_data and is_booked(booking_data[room]):
                booked_rooms.add(room)

        for key, value in booking_data.items():
            if matches_date(key):
                if isinstance(value, (list, tuple, set, pd.Series)):
                    booked_rooms.update(room for room in value if room in ROOMS)
                elif value in ROOMS:
                    booked_rooms.add(value)

    elif isinstance(booking_data, (list, tuple, set)):
        for item in booking_data:
            if isinstance(item, dict):
                room = item.get("room", item.get("Room"))
                booking_date = item.get(
                    "date", item.get("booking_date", item.get("Date"))
                )
                status = str(item.get("status", "")).lower()

                if room in ROOMS and (
                    matches_date(booking_date)
                    or status in {"booked", "reserved", "unavailable"}
                ):
                    booked_rooms.add(room)

    report = pd.DataFrame(
        {
            "Room": ROOMS,
            "Status": [
                "Booked" if room in booked_rooms else "Available"
                for room in ROOMS
            ],
        }
    )

    report["StatusCode"] = report["Status"].map(
        {"Available": 0, "Booked": 1}
    )

    ax = report.plot(
        kind="bar",
        x="Room",
        y="StatusCode",
        legend=False,
        ylabel="Booking Status",
        title=f"Room Booking Status for {date_str}",
    )
    ax.set_yticks([0, 1])
    ax.set_yticklabels(["Available", "Booked"])

    return report.drop(columns="StatusCode"), ax

