import json


def task_func(data_list, json_file_name="mean_values.json"):
    """Calculate the mean value for each position in a list of numeric sequences."""

    if not data_list:
        results = {}
    else:
        missing = object()
        results = {}

        for position, values in enumerate(
            itertools.zip_longest(*data_list, fillvalue=missing),
            start=1,
        ):
            present_values = [value for value in values if value is not missing]

            if not present_values:
                continue

            results[f"Position {position}"] = float(np.mean(present_values))

    if json_file_name is not None:
        with open(json_file_name, "w", encoding="utf-8") as json_file:
            json.dump(results, json_file, indent=4)

    return results

