import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source_path = Path(source_directory)
    target_path = Path(target_directory)

    if not source_path.exists():
        raise FileNotFoundError(source_directory)
    if not source_path.is_dir():
        raise NotADirectoryError(source_directory)

    target_path.mkdir(parents=True, exist_ok=True)

    allowed_extensions = {".txt", ".docx", ".xlsx", ".csv"}
    files = [
        Path(file_path)
        for file_path in glob.glob(
            os.path.join(source_directory, "**", "*"),
            recursive=True,
        )
        if Path(file_path).is_file()
        and Path(file_path).suffix in allowed_extensions
    ]

    moved_count = 0

    for source_file in files:
        destination = target_path / source_file.name

        if destination.exists():
            counter = 1
            while True:
                destination = (
                    target_path
                    / f"{source_file.stem}-{counter}{source_file.suffix}"
                )
                if not destination.exists():
                    break
                counter += 1

        shutil.move(str(source_file), str(destination))
        moved_count += 1

    return moved_count

