import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("Input df must be a pandas DataFrame.")

    result = df.copy()
    result.replace(dct, inplace=True)

    categorical_columns = result.select_dtypes(
        include=["object", "category", "string"]
    ).columns

    for column in categorical_columns:
        result[column] = LabelEncoder().fit_transform(result[column])

    numerical_columns = result.select_dtypes(include=["number"]).columns
    if columns is not None:
        numerical_columns = [
            column for column in columns if column in numerical_columns
        ]

    for column in numerical_columns:
        mean = result[column].mean()
        std = result[column].std()
        result[column] = (result[column] - mean) / std

    return result

import subprocess
import psutil
import time


def task_func(process_name: str) -> str:
    matching_processes = [
        process
        for process in psutil.process_iter(["name"])
        if process.info.get("name") == process_name
    ]

    if matching_processes:
        for process in matching_processes:
            try:
                process.terminate()
            except psutil.NoSuchProcess:
                pass

        _, alive = psutil.wait_procs(matching_processes, timeout=3)

        for process in alive:
            try:
                process.kill()
            except psutil.NoSuchProcess:
                pass

        time.sleep(0.1)
        subprocess.Popen(process_name, shell=True)
        return f"Process found. Restarting {process_name}."

    subprocess.Popen(process_name, shell=True)
    return f"Process not found. Starting {process_name}."

