def task_func(directory, file_pattern, suffix):
    result = {}

    for path in glob.glob(os.path.join(directory, "*")):
        if not os.path.isfile(path):
            continue

        filename = os.path.basename(path)
        if re.match(file_pattern, filename) and filename.endswith(suffix):
            mime_type, _ = mimetypes.guess_type(path)
            result[filename] = mime_type

    return result

from collections import Counter
import re

def task_func(word: str) -> list:
    cleaned_word = re.sub(r"[^a-zA-Z]", "", word.lower())

    if len(cleaned_word) < 2:
        return []

    combinations = (
        cleaned_word[index:index + 2]
        for index in range(len(cleaned_word) - 1)
    )
    most_common = Counter(combinations).most_common(1)

    return most_common

