import pandas as pd
import os
import json
from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if word_count <= 0:
        return []

    word_counter = Counter()

    for filename in os.listdir(json_dir_path):
        if not filename.lower().endswith(".json"):
            continue

        file_path = os.path.join(json_dir_path, filename)

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, json.JSONDecodeError):
            continue

        text_parts = []

        def collect_text(value):
            if isinstance(value, dict):
                for key, item in value.items():
                    if str(key).lower() in {"text", "content"} and isinstance(item, str):
                        text_parts.append(item)
                    elif isinstance(item, (dict, list)):
                        collect_text(item)
            elif isinstance(value, list):
                for item in value:
                    collect_text(item)

        if isinstance(data, str):
            text_parts.append(data)
        else:
            collect_text(data)

        for text in text_parts:
            words = re.findall(r"\b[\w']+\b", text.lower(), flags=re.UNICODE)
            word_counter.update(words)

    return word_counter.most_common(word_count)

import collections
import matplotlib.pyplot as plt


def task_func(data):
    if not data:
        return None

    scores_by_student = collections.defaultdict(list)

    for record in data:
        for student, score in record.items():
            if score is None:
                continue
            if score < 0:
                raise ValueError("Scores cannot be negative.")
            scores_by_student[student].append(score)

    averages = {
        student: sum(scores) / len(scores)
        for student, scores in scores_by_student.items()
        if scores
    }

    if not averages:
        return None

    students = list(averages.keys())
    scores = list(averages.values())

    _, ax = plt.subplots()
    ax.bar(students, scores, color="blue")
    ax.set_title("Average Student Scores")
    ax.set_xlabel("Student")
    ax.set_ylabel("Average Score")
    return ax

import subprocess
import platform
import time


def task_func(url) -> int:
    system = platform.system()

    if system == "Windows":
        command = ["cmd", "/c", "start", "", url]
    elif system == "Darwin":
        command = ["open", url]
    else:
        command = ["xdg-open", url]

    try:
        process = subprocess.Popen(command)
        return int(process.wait())
    except OSError:
        return 1

