import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    score_column = "score" if "score" in data.columns else data.columns[0]
    grade_column = "grade" if "grade" in data.columns else data.columns[1]

    scores = pd.to_numeric(data[score_column])

    grades = data[grade_column]
    grade_order = sorted(grades.dropna().unique())
    grade_mapping = {grade: rank for rank, grade in enumerate(grade_order)}
    encoded_grades = grades.map(grade_mapping)

    return float(pearsonr(scores, encoded_grades).statistic)

import numpy as np
import random
from scipy import stats


def task_func(list_of_lists, size=5, seed=0):
    random.seed(seed)

    values = []
    for values_list in list_of_lists:
        if not values_list:
            values_list = [random.randint(0, 100) for _ in range(size)]
        values.extend(values_list)

    if not values:
        raise ValueError("No values available to calculate statistics.")

    mode = stats.mode(values, keepdims=False).mode

    return {
        "mean": np.mean(values).item(),
        "median": np.median(values).item(),
        "mode": mode.item() if hasattr(mode, "item") else mode,
    }

