import os
import re
import shutil


def task_func(
    source_directory: str,
    target_directory: str,
    pattern: str = r"\d{4}",
) -> int:
    if not os.path.isdir(source_directory):
        return 0

    regex = re.compile(pattern)

    try:
        os.makedirs(target_directory, exist_ok=True)
    except OSError:
        return 0

    moved_count = 0

    try:
        entries = list(os.scandir(source_directory))
    except OSError:
        return 0

    for entry in entries:
        if not entry.is_file():
            continue

        if regex.search(entry.name) is None:
            continue

        destination = os.path.join(target_directory, entry.name)

        try:
            shutil.move(entry.path, destination)
        except (OSError, shutil.Error):
            continue

        moved_count += 1

    return moved_count

import time
import threading


def task_func(delay_time: float = 1.0, num_threads: int = 5):
    messages = [None] * num_threads

    def worker(thread_id: int):
        time.sleep(delay_time)
        messages[thread_id] = f"Delay in thread {thread_id} completed"

    threads = [
        threading.Thread(target=worker, args=(thread_id,))
        for thread_id in range(num_threads)
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return messages

