import os
import errno
import shutil

def task_func(filename, dest_dir):
    try:
        os.makedirs(dest_dir)
    except OSError as error:
        if error.errno != errno.EEXIST or not os.path.isdir(dest_dir):
            raise

    destination = os.path.join(dest_dir, os.path.basename(filename))
    shutil.copy(filename, destination)

    with open(filename, "w"):
        pass

    return os.path.abspath(destination)

import requests
import logging


def task_func(repo_url: str) -> dict:
    """Fetch and return information about a GitHub repository."""
    try:
        response = requests.get(repo_url)
        response.raise_for_status()

        try:
            repository_info = response.json()
        except (ValueError, TypeError) as exc:
            raise requests.exceptions.RequestException(
                "The GitHub API returned an invalid JSON response."
            ) from exc

        if not isinstance(repository_info, dict):
            raise requests.exceptions.RequestException(
                "The GitHub API response is not a repository object."
            )

        if repository_info.get("open_issues_count", 0) > 1000:
            logging.warning(
                "Repository has a large number of open issues: %s",
                repository_info["open_issues_count"],
            )

        return repository_info

    except requests.exceptions.HTTPError as exc:
        if (
            exc.response is not None
            and exc.response.status_code == 403
            and exc.response.headers.get("X-RateLimit-Remaining") == "0"
        ):
            logging.warning("GitHub API rate limit exceeded.")
        raise
    except requests.exceptions.RequestException:
        raise

