# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']


def task_func(n_keys, n_values):
    """Create a dictionary of randomly selected letter keys and integer lists."""
    if not isinstance(n_keys, int) or isinstance(n_keys, bool):
        raise TypeError("n_keys must be an integer")
    if not isinstance(n_values, int) or isinstance(n_values, bool):
        raise TypeError("n_values must be an integer")
    if n_keys < 0:
        raise ValueError("n_keys must be non-negative")
    if n_values < 0:
        raise ValueError("n_values must be non-negative")
    if n_keys > len(LETTERS):
        raise ValueError(f"n_keys cannot exceed {len(LETTERS)}")

    values = list(range(1, n_values + 1))
    return {key: values.copy() for key in random.sample(LETTERS, n_keys)}

import re
import os
import glob
from pathlib import Path

def task_func(pattern, directory, extensions):
    regex = re.compile(pattern, re.IGNORECASE)
    base_directory = os.path.abspath(directory)

    if isinstance(extensions, str):
        extensions = [extensions]
    elif extensions is None:
        extensions = []

    normalized_extensions = set()
    for extension in extensions:
        extension = str(extension).lower()
        if extension.startswith("*"):
            extension = extension[1:]
        if extension and not extension.startswith("."):
            extension = "." + extension
        normalized_extensions.add(extension)

    matching_files = []

    for file_path in glob.glob(os.path.join(base_directory, "*")):
        if not os.path.isfile(file_path):
            continue

        if normalized_extensions:
            suffix = Path(file_path).suffix.lower()
            if suffix not in normalized_extensions:
                continue

        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    matching_files.append(os.path.abspath(file_path))
        except (OSError, UnicodeError):
            continue

    return sorted(matching_files)

import subprocess
import time
import threading

def task_func(file_list):
    processes = []
    lock = threading.Lock()

    def start_process(file_path):
        process = subprocess.Popen(file_path)
        with lock:
            processes.append((file_path, process))

    threads = [
        threading.Thread(target=start_process, args=(file_path,))
        for file_path in file_list
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    exit_codes = [None] * len(file_list)
    process_by_file = {file_path: process for file_path, process in processes}

    for index, file_path in enumerate(file_list):
        exit_codes[index] = process_by_file[file_path].wait()

    return exit_codes

